using UotanStudio.Firmware.BoundedContexts.OtaDelta.Diff.PuffDiff;
using Xunit;

namespace UotanStudio.Tests.Firmware;

public class PuffDiffUpstreamTests
{
    [Fact]
    public void DynamicHuffmanPuffAndHuff_MatchPinnedPuffinVectors()
    {
        var deflate = Convert.FromHexString("");
        var puff = Convert.FromHexString("");
        Assert.Equal(puff, PuffDeflateCodec.Puff(deflate, 0, 3074, puff.Length));
        var result = new byte[deflate.Length];
        PuffDeflateCodec.Huff(puff, result, 0, 3074);
        Assert.Equal(deflate, result);
    }

    [Fact]
    public void EmptyBlocks_StopAtDeclaredPuffLimit()
    {
        var bits = new byte[12500];
        for (var i = 0; i < 10000; i++) bits[(i * 10 + 1) / 8] |= (byte)(1 << ((i * 10 + 1) & 7));
        var before = GC.GetAllocatedBytesForCurrentThread();
        Assert.ThrowsAny<IOException>(() => PuffDeflateCodec.Puff(bits, 0, 100000, 5));
        Assert.InRange(GC.GetAllocatedBytesForCurrentThread() - before, 0, 1024 * 1024);
    }

    [Fact]
    public void OversizedPuffLength_PublicApiRejectsBeforeAllocating()
    {
        // PUF1 version 1, source puff_length 268435457, empty target.
        var patch = Convert.FromHexString("505546310000000C080112061881808080011A00");
        var before = GC.GetAllocatedBytesForCurrentThread();
        Assert.Throws<UotanStudio.Firmware.BoundedContexts.OtaDelta.Payload.Exceptions.PayloadException>(() => PuffDiffApplier.Apply(patch, Array.Empty<byte>()));
        Assert.InRange(GC.GetAllocatedBytesForCurrentThread() - before, 0, 1024 * 1024);
    }
    // Puffin 35a231b2e5c0fa098f8fffbf264bbfcb837ba0a7 src/unittest_common.h.
    private const string Old = "1122636462666105003303006304004455";
    private const string New = "636462666105003366010500FAFF0102030405630400";
    private const string Forward = "";
    private const string Backward = "";

    [Theory]
    [InlineData(Old, New, Forward)]
    [InlineData(New, Old, Backward)]
    [InlineData(Old, "", "505546310000002D080112270A04081010320A040850100A0A0408601012120408101058120408781028120508A8011038181F1A0042534449464634300E000000000000000E000000000000000000000000000000425A683917724538509000000000425A683917724538509000000000425A683917724538509000000000")]
    [InlineData(Old, "0B16212C", "")]
    public void ChromiumPuffinPatch_IsByteExact(string source, string target, string patch)
        => Assert.Equal(Convert.FromHexString(target), PuffDiffApplier.Apply(Convert.FromHexString(patch), Convert.FromHexString(source)));
}